import{_ as o,a0 as l,w as d,s as r,ao as p,I as n,x as s,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 中删除文本中的回车字符 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中删除文本中的回车字符 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中删除文本中的回车字符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中删除文本中的回车字符 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190918 How to remove carriage returns from text files on Linux","title":"如何在 Linux 中删除文本中的回车字符","tag":"201909","desc":""},"relativePath":"201909/20190918 How to remove carriage returns from text files on Linux.md","filePath":"[post].md"}'),c={name:"201909/20190918 How to remove carriage returns from text files on Linux.md"};function h(u,e,g,k,f,x){const t=l("Link");return d(),r("div",null,[e[15]||(e[15]=p(`<h1 id="如何在-linux-中删除文本中的回车字符" tabindex="-1">如何在 Linux 中删除文本中的回车字符 <a class="header-anchor" href="#如何在-linux-中删除文本中的回车字符" aria-label="Permalink to “如何在 Linux 中删除文本中的回车字符”">​</a></h1><blockquote><p>当回车字符（<code>Ctrl+M</code>）让你紧张时，别担心。有几种简单的方法消除它们。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/25/214211xenk2dqfepx3xemm.jpg" alt=""></p><p>“回车”字符可以往回追溯很长一段时间 —— 早在打字机上就有一个机械装置或杠杆将承载纸滚筒的机架移到右边，以便可以重新在左侧输入字母。他们在 Windows 上的文本文件上保留了它，但从未在 Linux 系统上使用过。当你尝试在 Linux 上处理在 Windows 上创建的文件时，这种不兼容性有时会导致问题，但这是一个非常容易解决的问题。</p><p>如果你使用 <code>od</code>（<ruby>八进制转储<rt>octal dump</rt></ruby>）命令查看文件，那么回车（也用 <code>Ctrl+M</code> 代表）字符将显示为八进制的 15。字符 <code>CRLF</code> 通常用于表示 Windows 文本文件中的一行结束的回车符和换行符序列。那些注意看八进制转储的会看到 <code>\\r\\n</code>。相比之下，Linux 文本仅以换行符结束。</p><p>这有一个 <code>od</code> 输出的示例，高亮显示了行中的 <code>CRLF</code> 字符，以及它的八进制。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ od -bc testfile.txt</span></span>
<span class="line"><span>0000000 124 150 151 163 040 151 163 040 141 040 164 145 163 164 040 146</span></span>
<span class="line"><span>          T   h   i   s       i   s       a       t   e   s   t       f</span></span>
<span class="line"><span>0000020 151 154 145 040 146 162 157 155 040 127 151 156 144 157 167 163</span></span>
<span class="line"><span>          i   l   e       f   r   o   m       W   i   n   d   o   w   s</span></span>
<span class="line"><span>0000040 056 015 012 111 164 047 163 040 144 151 146 146 145 162 145 156  &lt;==</span></span>
<span class="line"><span>          .  \\r  \\n   I   t   &#39;   s       d   i   f   f   e   r   e   n  &lt;==</span></span>
<span class="line"><span>0000060 164 040 164 150 141 156 040 141 040 125 156 151 170 040 164 145</span></span>
<span class="line"><span>          t       t   h   a   n       a       U   n   i   x       t   e</span></span>
<span class="line"><span>0000100 170 164 040 146 151 154 145 015 012 167 157 165 154 144 040 142  &lt;==</span></span>
<span class="line"><span>          x   t       f   i   l   e  \\r  \\n   w   o   u   l   d       b  &lt;==</span></span></code></pre></div><p>虽然这些字符不是大问题，但是当你想要以某种方式解析文本，并且不希望就它们是否存在进行编码时，这有时候会产生干扰。</p><h3 id="_3-种从文本中删除回车符的方法" tabindex="-1">3 种从文本中删除回车符的方法 <a class="header-anchor" href="#_3-种从文本中删除回车符的方法" aria-label="Permalink to “3 种从文本中删除回车符的方法”">​</a></h3><p>幸运的是，有几种方法可以轻松删除回车符。这有三个选择：</p><h4 id="dos2unix" tabindex="-1">dos2unix <a class="header-anchor" href="#dos2unix" aria-label="Permalink to “dos2unix”">​</a></h4><p>你可能会在安装时遇到麻烦，但 <code>dos2unix</code> 可能是将 Windows 文本转换为 Unix/Linux 文本的最简单方法。一个命令带上一个参数就行了。不需要第二个文件名。该文件会被直接更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dos2unix testfile.txt</span></span>
<span class="line"><span>dos2unix: converting file testfile.txt to Unix format...</span></span></code></pre></div><p>你应该会发现文件长度减少，具体取决于它包含的行数。包含 100 行的文件可能会缩小 99 个字符，因为只有最后一行不会以 <code>CRLF</code> 字符结尾。</p><p>之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r--   1 shs  shs        121 Sep 14 19:11 testfile.txt</span></span></code></pre></div><p>之后：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r--   1 shs  shs        118 Sep 14 19:12 testfile.txt</span></span></code></pre></div><p>如果你需要转换大量文件，不用每次修复一个。相反，将它们全部放在一个目录中并运行如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type f -exec dos2unix {} \\;</span></span></code></pre></div><p>在此命令中，我们使用 <code>find</code> 查找常规文件，然后运行 <code>dos2unix</code> 命令一次转换一个。命令中的 <code>{}</code> 将被替换为文件名。运行时，你应该处于包含文件的目录中。此命令可能会损坏其他类型的文件，例如除了文本文件外在上下文中包含八进制 15 的文件（如，镜像文件中的字节）。</p><h4 id="sed" tabindex="-1">sed <a class="header-anchor" href="#sed" aria-label="Permalink to “sed”">​</a></h4><p>你还可以使用流编辑器 <code>sed</code> 来删除回车符。但是，你必须提供第二个文件名。以下是例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -e “s/^M//” before.txt &gt; after.txt</span></span></code></pre></div><p>一件需要注意的重要的事情是，请不要输入你看到的字符。你必须按下 <code>Ctrl+V</code> 后跟 <code>Ctrl+M</code> 来输入 <code>^M</code>。<code>s</code> 是替换命令。斜杠将我们要查找的文本（<code>Ctrl + M</code>）和要替换的文本（这里为空）分开。</p><h4 id="vi" tabindex="-1">vi <a class="header-anchor" href="#vi" aria-label="Permalink to “vi”">​</a></h4><p>你甚至可以使用 <code>vi</code> 删除回车符（<code>Ctrl+M</code>），但这里假设你没有打开数百个文件，或许也在做一些其他的修改。你可以键入 <code>:</code> 进入命令行，然后输入下面的字符串。与 <code>sed</code> 一样，命令中 <code>^M</code> 需要通过 <code>Ctrl+V</code> 输入 <code>^</code>，然后 <code>Ctrl+M</code> 插入 <code>M</code>。<code>%s</code> 是替换操作，斜杠再次将我们要删除的字符和我们想要替换它的文本（空）分开。 <code>g</code>（全局）意味在所有行上执行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:%s/^M//g</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p><code>dos2unix</code> 命令可能是最容易记住的，也是从文本中删除回车的最可靠的方法。其他选择使用起来有点困难，但它们提供相同的基本功能。</p><hr>`,31)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(t,{href:"https://www.networkworld.com/article/3438857/how-to-remove-carriage-returns-from-text-files-on-linux.html"},{default:a(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3438857/how-to-remove-carriage-returns-from-text-files-on-linux.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),i(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:a(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const w=o(c,[["render",h]]);export{C as __pageData,w as default};
